import json,glob,os,sys
B="/home/user/fortress-transcripts-blinded/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents"
notes=["process-engineering/labor.md","testing-practices.md","context-study.md","checking-roles-cost.md","harness-cache-cost.md"]
res={n:{} for n in notes}
for j in sorted(glob.glob(B+"/agent-*.jsonl")):
    aid=os.path.basename(j)[6:-6]
    try: txt=open(j).read()
    except: continue
    if not any(n.split('/')[-1] in txt for n in notes): continue
    for ln,l in enumerate(txt.split("\n")):
        if not l.strip(): continue
        try: d=json.loads(l)
        except: continue
        m=d.get("message")
        if not m or not isinstance(m.get("content"),list): continue
        for c in m["content"]:
            if c.get("type")!="tool_use": continue
            inp=c["input"]; nm=c["name"]
            for n in notes:
                base=n.split('/')[-1]
                if nm in("Write","Edit") and inp.get("file_path","").endswith(base):
                    res[n].setdefault(aid,[]).append((nm,ln))
                elif nm=="Bash":
                    cmd=inp.get("command","")
                    if base in cmd and ("git commit" in cmd or "<<" in cmd or "> " in cmd and "process-engineering" in cmd):
                        k="BashCommit" if "git commit" in cmd else "BashWrite"
                        res[n].setdefault(aid,[]).append((k,ln))
for n,v in res.items():
    print("==",n)
    for a,lst in v.items():
        from collections import Counter
        print("  ",a,dict(Counter(x[0] for x in lst)), "first line",lst[0][1])
EOF
python3 find_authors.py

